// Document checklist per project, from the file names found in the project folder
const raw = $input.first().json;
const b = raw.body ?? raw;

const SIGNED = /(contract[_ -]?signed|signed[_ -]?contract|smlouva.*podepsan)/i;
const NOT_SIGNED = /(not[_ -]?signed|nepodepsan|draft|navrh|návrh)/i;
const APPROVAL = /(building[_ -]?office[_ -]?approval|occupancy|souhlas|kolaudac)/i;

const projects = (b.projects || []).map(p => {
  const docs = (p.documents || []).map(x => (typeof x === 'string' ? x : x.name || ''));
  const contractSigned = docs.some(n => SIGNED.test(n) && !NOT_SIGNED.test(n));
  const contractDraft = docs.some(n => NOT_SIGNED.test(n));
  const approval = docs.some(n => APPROVAL.test(n));
  const entries = (p.entries || []).slice().sort((a, c) => String(a.week).localeCompare(String(c.week)));
  const latest = entries[entries.length - 1] || null;

  const flags = [];
  if (!contractSigned) flags.push({ severity: 'blocker', text: contractDraft ? 'Contract not signed yet (draft only)' : 'No contract in the project folder' });
  if (!approval) flags.push({ severity: 'info', text: 'No building office approval in the folder yet' });
  if (entries.length === 0) flags.push({ severity: 'warning', text: 'No weekly report yet' });

  return {
    id: p.id ?? null,
    name: p.name,
    company: p.company || '',
    weeks_reported: entries.length,
    latest_week: latest?.week ?? null,
    is_new_project: entries.length <= 1,
    documents: docs,
    checklist: {
      contract_signed: contractSigned,
      contract_draft_only: !contractSigned && contractDraft,
      building_office_approval: approval,
    },
    flags,
    open_issues: (latest?.issues || []).filter(i => (i.severity || 'info') !== 'info'),
    latest_summary: latest?.project_page_entry?.body ?? latest?.summary ?? '',
  };
});

return [{
  json: {
    started_ms: Date.now(),
    week: b.week || '',
    model: b.model || 'gpt-4o-mini',
    language: b.language || 'en',
    projects,
  },
}];

// Prompts for the one-page management summary, based only on the checklist data
const d = $input.first().json;
const system_prompt = `You write the weekly management summary for the CEO and the head of construction of a Czech construction company (solar, battery storage, buildings).
Use ONLY the data given. Never invent numbers or facts. Language: "${d.language}".
Return ONLY a JSON object:
{
  "headline": string,
  "attention": [{"project": string, "text": string}],
  "highlights": [{"project": string, "text": string}],
  "summary_markdown": string
}
- headline: one sentence on how the portfolio is doing this week.
- attention: what management must act on, blockers first (unsigned contracts, delays, waiting for the client).
- highlights: progress worth sharing, good candidates for marketing.
- summary_markdown: the full one-page summary in Markdown: headline, a table (Project | Latest week | Progress | Contract | Approval | Flags), then Attention and Highlights.`;
const user_prompt = `Week: ${d.week}\n\nPROJECTS (JSON):\n${JSON.stringify(d.projects, null, 1)}`;
return [{ json: { ...d, system_prompt, user_prompt } }];

// Combine the deterministic document checklist with the LLM summary
const d = $('Build summary prompts').first().json;
const findText = (x) => {
  if (x == null) return null;
  if (Array.isArray(x)) { for (const v of x) { const t = findText(v); if (t != null) return t; } return null; }
  if (typeof x === 'object') {
    if (x.text != null) return x.text;
    for (const k of ['output', 'content', 'message', 'choices']) { if (x[k] != null) { const t = findText(x[k]); if (t != null) return t; } }
  }
  return null;
};
const raw = findText($input.first().json);
let out;
if (raw && typeof raw === 'object') out = raw;
else {
  const s = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
  try { out = JSON.parse(s); } catch (e) { throw new Error('The model did not return valid JSON: ' + s.slice(0, 400)); }
}
const totals = {
  projects: d.projects.length,
  contracts_missing: d.projects.filter((p) => !p.checklist.contract_signed).length,
  approvals_present: d.projects.filter((p) => p.checklist.building_office_approval).length,
  new_projects: d.projects.filter((p) => p.is_new_project).length,
  open_issues: d.projects.reduce((n, p) => n + p.open_issues.length, 0),
};
return [{
  json: {
    week: d.week,
    generated_at: new Date().toISOString(),
    totals,
    headline: out.headline ?? '',
    attention: out.attention ?? [],
    highlights: out.highlights ?? [],
    summary_markdown: out.summary_markdown ?? '',
    checklist: d.projects,
    processing_seconds: Math.round((Date.now() - d.started_ms) / 100) / 10,
  },
}];
